use std::io::{Read, Write};
use rust_unit_merge::topology::*;

fn fnv(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &b in bytes { h ^= b as u64; h = h.wrapping_mul(0x100000001b3); }
    h
}

fn build(spec: &[String]) -> TopologyCase {
    let mode = spec[0].as_str();
    let num = |i: usize| -> usize { spec[i].parse().unwrap() };
    match mode {
        "clos" => build_clos(num(1), 1, None, None, num(3) != 0,
                            if spec[2] == "pod" { ClosSourceGroupScope::Pod } else { ClosSourceGroupScope::Tor }),
        "leaf-spine" => build_leaf_spine(num(1), num(2), 1),
        "torus2d" => build_torus2d(num(1), 1, if spec[2] == "row" { Torus2DSourceGroupScope::Row } else { Torus2DSourceGroupScope::Host }),
        "torus3d" => build_torus3d(num(1), 1, if spec[2] == "line" { Torus3DSourceGroupScope::Line } else { Torus3DSourceGroupScope::Host }),
        "dragonfly" => build_dragonfly(num(1), num(2), num(3), Some(1), 1.0, 1, 0,
                            match spec[4].as_str() { "router" => DragonflySourceGroupScope::Router, "group" => DragonflySourceGroupScope::Group, _ => DragonflySourceGroupScope::SourceTargetGroup }),
        "dragonfly-plus" => build_dragonfly_plus(num(1), num(2), num(3), num(4), num(5) != "0", 1, 0,
                            if spec[6] == "group" { DragonflyPlusSourceGroupScope::Group } else { DragonflyPlusSourceGroupScope::Tor }),
        _ => panic!("mode"),
    }
}

fn main() {
    let mut raw = String::new();
    std::io::stdin().read_to_string(&mut raw).unwrap();
    let verbose = std::env::args().any(|a| a == "-v");
    let mut out = String::new();
    for line in raw.lines() {
        if line.trim().is_empty() { continue; }
        let spec: Vec<String> = line.split_whitespace().map(|s| s.to_string()).collect();
        let case = build(&spec);
        let p = &case.problem;
        let n = p.num_nodes;
        let domain: Vec<usize> = match p.demand_merge_classes.as_ref() {
            Some(c) => c.clone(),
            None => {
                let mut owner = vec![usize::MAX; n];
                for (id, mem) in p.source_merge_groups.iter().enumerate() { for &x in mem { owner[x] = id; } }
                p.demands.iter().map(|d| owner[d.src]).collect()
            }
        };
        let mut acc: u64 = 0xcbf29ce484222325;
        let mut buf = String::new();
        for (i, d) in p.demands.iter().enumerate() {
            buf.clear();
            buf.push_str(&d.src.to_string()); buf.push(' ');
            buf.push_str(&d.dst.to_string()); buf.push(' ');
            buf.push_str(&domain[i].to_string());
            for x in d.footprint.iter() { buf.push(','); buf.push_str(&x.to_string()); }
            buf.push('\n');
            if verbose { out.push_str(&buf); }
            acc = fnv(&[(&acc.to_le_bytes()[..]), buf.as_bytes()].concat());
        }
        if !verbose { out.push_str(&format!("{} {} {:016x}\n", n, p.demands.len(), acc)); }
    }
    let stdout = std::io::stdout();
    stdout.lock().write_all(out.as_bytes()).unwrap();
}
EOF
